mapper.select:
SELECT id, date, time, product_name, code_number, in_quantity, out_quantity,
       specification, price, receiver, remark,
       type, created_by, created_at, target_system
FROM ${table}
WHERE deleted_at IS NULL

    AND (product_name LIKE CONCAT('%', #{keyword}, '%')
         OR code_number LIKE CONCAT('%', #{keyword}, '%')
         OR remark LIKE CONCAT('%', #{keyword}, '%'))


    AND date >= #{startDate}


    AND date <= #{endDate}

-- 对齐旧系统分店 stockedit：ORDER BY date ASC, time ASC（旧在上、新在底）
ORDER BY date ASC, time ASC, id ASC
LIMIT #{size} OFFSET #{offset}

SELECT COUNT(*) FROM ${table}
WHERE deleted_at IS NULL

    AND (product_name LIKE CONCAT('%', #{keyword}, '%')
         OR code_number LIKE CONCAT('%', #{keyword}, '%')
         OR remark LIKE CONCAT('%', #{keyword}, '%'))


    AND date >= #{startDate}


    AND date <= #{endDate}

mapper.update:
UPDATE ${table} SET deleted_at = NOW(), deleted_by = #{deletedBy}
WHERE product_name = #{productName} AND receiver = #{receiver}
  AND target_system = #{targetSystem} AND deleted_at IS NULL

mapper.select:
SELECT date, time, product_name, code_number, in_quantity, out_quantity,
       specification, price, receiver, remark, type, target_system
FROM ${table}
WHERE deleted_at IS NULL
  AND REPLACE(product_name, '&amp;', '&') = REPLACE(#{productName}, '&amp;', '&')

    AND date >= #{startDate}


    AND date <= #{endDate}

ORDER BY date ASC, time ASC, id ASC

SELECT COUNT(*) FROM (
    SELECT remark_number
    FROM stockinout_data
    WHERE product_name = #{productName}
      AND remark_number = #{remarkNumber}
      AND product_remark_checked = 1
      AND deleted_at IS NULL
    GROUP BY remark_number
    HAVING SUM(in_quantity) - SUM(out_quantity) > 0
) t
